import sys
import subprocess
import re

def get_clipboard():
    """Reads content from the macOS clipboard."""
    return subprocess.check_output(['pbpaste'], text=True)

def set_clipboard(text):
    """Writes content to the macOS clipboard."""
    process = subprocess.Popen(['pbcopy'], stdin=subprocess.PIPE)
    process.communicate(input=text.encode('utf-8'))
    return text

def to_sentence_case(text):
    """Converts a block of text to sentence case."""
    sentences = re.split(r'([.!?]\s*)', text)
    output = []
    for i, sentence in enumerate(sentences):
        if i % 2 == 0 and sentence.strip():
            output.append(sentence.strip().capitalize())
        else:
            output.append(sentence)
    return "".join(output)

def to_camel_case(text):
    """Converts a string to camelCase."""
    parts = re.split(r'[\s_-]+', text)
    if not parts:
        return ""
    return parts[0].lower() + "".join(word.capitalize() for word in parts[1:])

def to_cap_case(text):
    """Capitalises each word and removes dashes/underscores."""
    parts = re.split(r'[\s_-]+', text.strip())
    return " ".join(word.capitalize() for word in parts if word)

# The command is passed from Alfred
command = sys.argv[1].lower()

# Read the initial content from the clipboard
original_text = get_clipboard()
transformed_text = ""

# --- Main Logic ---
if command == 'upper':
    transformed_text = original_text.upper()
elif command == 'lower':
    transformed_text = original_text.lower()
elif command == 'snake':
    transformed_text = original_text.replace(' ', '_')
elif command == 'spinal':
    transformed_text = original_text.replace(' ', '-')
elif command == 'space':
    transformed_text = original_text.replace('_', ' ').replace('-', ' ')
elif command in ('lower-spinal', 'kebab-lower', 'slug'):
    transformed_text = re.sub(r'\s+', '-', original_text.strip().lower())
elif command == 'sentence' or command == 'sentences case':
    transformed_text = to_sentence_case(original_text)
elif command == 'camel':
    transformed_text = to_camel_case(original_text)
elif command == 'cap':
    transformed_text = to_cap_case(original_text)
else:
    transformed_text = "Error: Unknown command."

# Update the clipboard with the new text
set_clipboard(transformed_text)

# Pass the command name to the notification
print(f"'{command.capitalize()}' case applied.")
